INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `instruction`, `timer_seconds`) VALUES (1,1,1,'Pon a calentar un cazo con abundante agua ligeramente salada y una hoja de laurel. Cuando rompa a hervir, incorpora el arroz redondo y cuécelo a fuego medio para que quede suelto y en su punto.',960),(2,1,2,'Mientras tanto, en una sartén con la mitad del AOVE medido, dora el diente de ajo picado y vierte el tomate natural triturado con una pizca de sal, pimienta y orégano o albahaca fresca. Cocina a fuego suave hasta reducir.',600),(3,1,3,'Corta el plátano de Canarias longitudinalmente y dóralo en una sartén antiadherente bien caliente sin añadir grasa extra hasta que caramelicen sus azúcares naturales por ambas caras.',180),(4,1,4,'En la misma sartén antiadherente con unas gotas de AOVE, haz el huevo a la plancha (tápalo para que cuaje la clara manteniendo la yema líquida) y emplata el arroz escurrido con el tomate, el huevo y el plátano.',150),(5,2,1,'Lava las lentejas pardinas bajo el grifo. Pela y corta en dados pequeños la zanahoria, el calabacín, el puerro y la cebolla.',240),(6,2,2,'En una cazuela incorpora las lentejas, todas las hortalizas troceadas, una hoja de laurel y cubre con agua o caldo de verduras dos dedos por encima. Lleva a ebullición y baja a fuego suave.',1500),(7,2,3,'Retira dos cucharadas de verduras cocidas con un cacillo de caldo, tritúralas junto al pimentón dulce de la Vera y devuélvelas a la olla con el hilo de AOVE en crudo para trabar el caldo de forma hipocalórica.',180),(8,3,1,'Dora los ajos laminados en una cazuela baja con el AOVE medido a fuego medio sin que se quemen.',120),(9,3,2,'Aparta un instante del fuego, añade el pimentón de la Vera, remueve rápido e incorpora el tomate natural triturado. Cocina hasta obtener un sofrito concentrado.',300),(10,3,3,'Añade los garbanzos lavados y escurridos, un chorrito de caldo y las hojas de espinaca fresca lavadas. Tapa para que las espinacas reduzcan su volumen e integren sabores.',360),(11,4,1,'En una olla rehoga la cebolla y la zanahoria en medias lunas junto a las pencas blancas de la acelga picadas con el AOVE medido y una pizca de sal.',360),(12,4,2,'Vierte el caldo de verduras caliente y las alubias blancas cocidas. Cocina a fuego medio-bajo para que el caldo tome cuerpo.',600),(13,4,3,'Incorpora las hojas verdes de las acelgas troceadas en los últimos minutos para conservar sus vitaminas y sirve bien caliente.',300),(14,5,1,'Cuece los huevos en un cazo con agua hirviendo hasta que estén duros, enfríalos en agua con hielo y pélalos.',600),(15,5,2,'Lava y escurre muy bien las alubias blancas. Pica en dados pequeños (brunoise) el tomate maduro, el pimiento rojo, el pimiento verde y la cebolleta tierna.',300),(16,5,3,'Mezcla en una ensaladera las alubias con las hortalizas crujientes, corona con el huevo duro en cuartos y aliña con el AOVE medido, vinagre y orégano.',120),(17,6,1,'Si usas lenteja seca, cuécela al dente (o enjuaga y templa ligeramente las lentejas ya cocidas).',300),(18,6,2,'Corta los pimientos rojos asados en tiras finas, la cebolleta en juliana y ralla la zanahoria fresca.',240),(19,6,3,'Mezcla las lentejas tibias con las verduras y emulsiona el AOVE con vinagre de Jerez y sal en escamas para que absorban el aliño.',120),(20,7,1,'Escurre y seca los garbanzos con papel absorbente. Corta el calabacín en dados medianos y lamina las setas o champiñones.',240),(21,7,2,'En una sartén amplia bien caliente con el AOVE, saltea el calabacín y las setas con el ajo picado hasta que doren sin soltar agua.',360),(22,7,3,'Incorpora los garbanzos y saltea a fuego vivo con perejil fresco y pimienta negra recién molida hasta que tomen textura exterior crujiente.',240),(23,8,1,'Rehoga el puerro en rodajas y la calabaza pelada en dados en una cazuela con el AOVE y un chorrito de caldo.',420),(24,8,2,'Cubre con el resto del caldo de verduras y deja cocer hasta que la calabaza esté muy tierna.',600),(25,8,3,'Aplasta ligeramente un par de trozos de calabaza contra el borde para espesar el caldo, añade las alubias blancas y da un hervor suave.',300),(26,9,1,'Pica muy menudo el tomate maduro, el pimiento verde italiano y el pepino pelado. Mézclalos en un bol con los garbanzos cocidos y el AOVE.',300),(27,9,2,'Calienta una plancha al máximo y marca los dados de atún fresco salpimentados apenas vuelta y vuelta para que queden jugosos en el centro.',120),(28,9,3,'Sirve la pipirrana de garbanzos bien fresca coronada con los dados de atún recién salidos de la plancha.',60),(29,10,1,'Limpia los corazones de alcachofa, córtalos en cuartos y rehógalos brevemente con la cebolla y la zanahoria en la cazuela.',300),(30,10,2,'Añade las lentejas pardinas y el caldo de verduras caliente. Cocina a fuego suave con la cazuela semitapada.',1500),(31,10,3,'Rectifica de sal, añade perejil picado y deja reposar antes de servir para asentar el caldo.',180),(32,11,1,'Saltea los espárragos trigueros limpios en una plancha caliente con unas gotas de AOVE y sal gruesa hasta que estén tiernos y al dente.',360),(33,11,2,'En la misma plancha marca los lomos de merluza primero por el lado de la piel o base y luego dale la vuelta para que quede nacarada y jugosa.',300),(34,11,3,'Dora los ajos laminados con el resto del AOVE, desglasa con zumo de limón y vierte sobre la merluza y los trigueros.',120),(35,12,1,'Precalienta el horno a 200 °C. Coloca en una fuente las patatas cortadas en rodajas finas y la cebolla en juliana con el caldo de verduras y hornea.',900),(36,12,2,'Coloca los lomos de lubina salpimentados sobre la cama de patata y cebolla, añade rodajas de limón y pulveriza el AOVE medido.',600),(37,12,3,'Espolvorea perejil fresco picado al sacar del horno y sirve inmediatamente con los jugos de la bandeja.',60),(38,13,1,'Precalienta el horno a 190 °C. Dispón en la bandeja una base húmeda de rodajas de tomate maduro y cebolla en pluma.',300),(39,13,2,'Coloca la dorada abierta a la espalda sobre las verduras, sazona y hornea hasta que la carne se separe fácilmente de la espina.',780),(40,13,3,'Termina con ajo muy picado, perejil y el hilo de AOVE virgen extra sobre los lomos calientes.',60),(41,14,1,'Corta en juliana fina el puerro y la zanahoria. Colócalos en el centro de un pliego amplio de papel de hornear.',240),(42,14,2,'Sitúa el lomo de salmón encima, añade una rodaja de limón, eneldo, sal y pimienta. Cierra el paquete herméticamente doblando los bordes.',180),(43,14,3,'Hornea a 200 °C para que el vapor interior cocine el salmón y las verduras en su propio jugo.',720),(44,15,1,'Rellena la trucha limpia abierta con los taquitos o loncha fina de jamón serrano magro sin grasa blanca.',180),(45,15,2,'Hornea a 195 °C sobre papel vegetal sin añadir harinas ni rebozados hasta que la trucha esté en su punto.',600),(46,15,3,'Acompaña en el plato con la ensalada fresca de brotes verdes y tomate aliñado.',120),(47,16,1,'Prepara la picada machacando el diente de ajo con perejil fresco, zumo de limón y el AOVE medido.',180),(48,16,2,'Asa las rodajas de calabacín en la plancha bien caliente por ambas caras con una pizca de sal y orégano.',300),(49,16,3,'Marca el filete de emperador a fuego fuerte 90 segundos por lado y báñalo al salir con la picada verde.',180),(50,17,1,'Forra la bandeja de horno con papel vegetal y coloca las sardinas limpias junto con los pimientos verdes y el tomate en mitades.',240),(51,17,2,'Añade rodajas de limón, ajo picado y pincela con el AOVE. Hornea a 200 °C hasta que la piel quede dorada.',600),(52,17,3,'Sirve las sardinas recién horneadas acompañadas de los pimientos y el tomate asado.',60),(53,18,1,'Extiende los boquerones abiertos sin espina en una fuente de horno con la piel hacia abajo.',180),(54,18,2,'Reparte por encima el ajo muy picado, perejil, zumo de limón y el AOVE. Hornea a 200 °C.',480),(55,18,3,'Sírvelos calientes junto a la ensalada fresca de brotes verdes.',60),(56,19,1,'Pocha la cebolla y el pimiento rojo muy picados en una cazuela con el AOVE a fuego lento.',360),(57,19,2,'Vierte el tomate natural triturado y cocina suavemente hasta que la salsa pierda la acidez y espese.',600),(58,19,3,'Incorpora los dados de bonito limpio salpimentados, apaga el fuego y deja que se cocinen con el calor residual 3 minutos con la cazuela tapada.',180),(59,20,1,'Corta la cebolla dulce en juliana fina y póchala en cazuela con una hoja de laurel, el AOVE y el caldo de verduras con tapa puesta.',720),(60,20,2,'Cuando la cebolla esté transparente y caramelizada, añade las tiras de pimiento asado.',180),(61,20,3,'Incorpora los tacos de atún fresco y cocínalos 2 minutos por cara para que queden súper tiernos.',240),(62,21,1,'Si no tienes la escalivada lista del Batch Cooking, asa o calienta las tiras de pimiento rojo, berenjena y cebolla con una pizca de sal y AOVE.',300),(63,21,2,'Calienta la plancha a fuego medio-alto y dora los filetes de pechuga de pollo previamente marinados con limón y tomillo.',300),(64,21,3,'Sirve los filetes dorados acompañados de una generosa ración de escalivada templada.',60),(65,22,1,'Dora los dientes de ajo enteros con un golpe seco en una cazuela con el AOVE y sella los dados de pollo salpimentados.',360),(66,22,2,'Añade los champiñones laminados y saltea hasta que tomen color dorado.',300),(67,22,3,'Vierte el caldo de verduras (y un toque opcional de vino blanco), tapa y cocina a fuego medio hasta que reduzca la salsa.',480),(68,23,1,'Sella los medallones de solomillo de pavo en una cazuela con el AOVE y retíralos a un plato.',240),(69,23,2,'En el mismo fondo pocha la cebolla, el puerro y la zanahoria troceada con una rama de tomillo y cubre con el caldo.',600),(70,23,3,'Tritura la mitad de las verduras para ligar la salsa, reincorpora el pavo y da un hervor suave de 4 minutos.',240),(71,24,1,'Mezcla los dados de pechuga de pollo con pimentón dulce, comino, orégano, ajo en polvo, sal y el AOVE medido.',180),(72,24,2,'Ensarta en brochetas alternando los dados de pollo marinado con medias lunas de calabacín y tacos de pimiento rojo.',240),(73,24,3,'Cocina las brochetas en la plancha bien caliente girándolas para que se doren de forma uniforme.',480),(74,25,1,'Mezcla la carne picada magra de pavo con el calabacín rallado crudo, ajo, perejil y sal. Forma las albóndigas y hornéalas a 200 °C sobre papel vegetal.',720),(75,25,2,'Mientras se hornean, pocha la cebolla y la zanahoria con el caldo de verduras y tritúralas hasta obtener una salsa española ligera.',480),(76,25,3,'Introduce las albóndigas horneadas en la salsa caliente y cocínalas 5 minutos para que se impregnen bien.',300),(77,26,1,'Dora los trozos de conejo magro junto a los ajos laminados y una rama de romero en la cazuela con el AOVE.',480),(78,26,2,'Incorpora los corazones de alcachofa en cuartos y rehoga 2 minutos.',180),(79,26,3,'Vierte el caldo de verduras caliente, tapa la cazuela y cocina a fuego suave hasta que la carne esté muy tierna.',900),(80,27,1,'En una sartén pequeña a fuego muy bajo, confita las tiras de pimiento del piquillo con el ajo laminado y media cucharadita de AOVE.',420),(81,27,2,'Calienta la plancha a fuego fuerte y marca los filetes de lomo magro vuelta y vuelta para que no pierdan jugosidad.',180),(82,27,3,'Sirve el lomo cubierto con los pimientos del piquillo templados y los brotes verdes al lado.',60),(83,28,1,'Sella los trozos de pollo sin piel en una cazuela y añade la zanahoria en dados y el tomate natural.',360),(84,28,2,'Incorpora la patata chascada medida, cubre ligeramente con agua o caldo y cocina tapado a fuego medio.',900),(85,28,3,'Añade los guisantes tiernos en los últimos 4 minutos de cocción para que queden tersos y dulces.',240),(86,29,1,'Corta la pechuga de pollo, el pimiento rojo y el pimiento verde en tiras finas del mismo tamaño.',240),(87,29,2,'Saltea a fuego vivo en sartén con el AOVE, primero los pimientos 4 minutos y después las tiras de pollo con comino y pimienta.',420),(88,29,3,'Dispón las hojas enteras y crujientes de cogollo de lechuga a modo de barquitas y rellénalas con el salteado caliente.',120),(89,30,1,'Prepara la ensalada murciana mezclando el tomate troceado, la cebolleta en juliana fina y el huevo duro en gajos con el AOVE.',240),(90,30,2,'Marca los filetes de pavo salpimentados con orégano en la plancha bien caliente.',240),(91,30,3,'Sirve los filetes recién hechos acompañados del moje murciano fresco.',60),(92,31,1,'Precalienta el horno a 200 °C. Coloca el contramuslo limpio junto con los gajos de patata y bastones de calabacín en una fuente.',240),(93,31,2,'Riega con zumo de limón, romero fresco, sal, pimienta y el AOVE medido. Hornea hasta que todo esté dorado.',1200),(94,31,3,'Salsea el pollo con los jugos aromáticos del fondo de la bandeja al emplatar.',60),(95,32,1,'Corta en dados regulares el pimiento rojo, el pimiento verde, el calabacín y la berenjena.',300),(96,32,2,'Póchalos en una sartén amplia con el AOVE y la tapa puesta a fuego medio para que se cocinen en su propio jugo; añade el tomate natural y cocina 10 minutos más.',900),(97,32,3,'Haz un hueco en el centro del pisto caliente, casca el huevo campero, tapa la sartén y deja que escalfe hasta que la clara cuaje.',240),(98,33,1,'Corta el calabacín en medias lunas finas y la cebolla en juliana. Cocínalos 5 minutos al vapor o en estuche al microondas para ablandarlos sin grasa.',300),(99,33,2,'Pásalos 2 minutos por la sartén con la mitad del AOVE para darles toque dorado y mézclalos en un bol con los huevos batidos.',180),(100,33,3,'Cuaja la tortilla en la sartén antiadherente por ambas caras dejándola jugosa en el interior.',240),(101,34,1,'Cuece al vapor los dados de calabacín pelado durante 6 minutos y déjalos enfriar (harán la función espesante del pan).',360),(102,34,2,'En el vaso de la batidora tritura a máxima potencia los tomates pera maduros, el calabacín cocido, el medio ajo y una pizca de sal.',180),(103,34,3,'Con la batidora en marcha añade el AOVE en hilo fino para emulsionar y sírvelo frío con el huevo duro y el jamón magro picados.',120),(104,35,1,'Trocea los tomates maduros lavados, el pepino parcialmente pelado y el pimiento verde italiano sin semillas.',240),(105,35,2,'Tritura todo con el AOVE, un chorrito de vinagre de Jerez, sal y un poco de agua fría hasta lograr una textura fina.',180),(106,35,3,'Sirve bien frío en cuenco coronado con abundante huevo duro picado y daditos de verdura para masticar.',60),(107,36,1,'Cuece al vapor o en agua hirviendo las judías verdes, la zanahoria, los corazones de alcachofa y los guisantes hasta que queden al dente.',720),(108,36,2,'En una sartén dora ligeramente el ajo con los taquitos de jamón serrano magro y media cucharadita de AOVE; incorpora las verduras escurridas y saltea.',240),(109,36,3,'Corona cada plato de menestra con un huevo poché recién hecho.',180),(110,37,1,'Cuece en una olla la calabaza troceada, el puerro y la zanahoria cubiertos con el caldo de verduras casero.',900),(111,37,2,'Paralelamente cuece el huevo en agua hirviendo durante exactamente 6 minutos, enfríalo y pélalo.',360),(112,37,3,'Tritura las verduras con el requesón 0% hasta obtener una crema sedosa y sírvela con el huevo abierto en el centro y unas gotas de AOVE.',120),(113,38,1,'Limpia y trocea los espárragos trigueros y lamina los champiñones.',180),(114,38,2,'Saltea en sartén con el AOVE y los ajetes a fuego medio-alto hasta que los trigueros estén tiernos.',360),(115,38,3,'Vierte los huevos ligeramente batidos, baja el fuego al mínimo y remueve sin parar retirando del calor antes de que se seque.',120),(116,39,1,'Abre la berenjena longitudinalmente, haz cortes en rombo en su pulpa y ásala en el horno o microondas hasta que esté tierna. Vacía la pulpa.',600),(117,39,2,'En una sartén sofríe la cebolla y el pavo picado con la pulpa de berenjena picada y el tomate natural.',480),(118,39,3,'Rellena las barquitas de berenjena, cubre con el requesón batido con nuez moscada y gratina 5 minutos al horno.',300),(119,40,1,'Corta el tomate maduro en gajos y la cebolleta en pluma fina. Alíñalos con orégano, sal y la mitad del AOVE.',180),(120,40,2,'Bate los huevos con una cucharada de agua fría, sal y perejil fresco muy picado.',120),(121,40,3,'Cuaja la tortilla francesa en la sartén caliente con el resto del AOVE doblándola sobre sí misma para que quede jugosa.',120),(122,41,1,'Trocea el calabacín pelado a franjas y la parte blanca del puerro. Cuécelos con el caldo de verduras durante 14 minutos.',840),(123,41,2,'Tritura con el requesón o queso fresco 0%, sal, pimienta blanca y el hilo de AOVE hasta lograr una textura fina.',120),(124,41,3,'Dora las tiras de pechuga de pavo en una sartén en seco y colócalas crujientes sobre la crema caliente.',180),(125,42,1,'Limpia las judías verdes planas, córtalas en bastones y cuécelas al vapor junto a la patata en dados hasta que estén tiernas.',840),(126,42,2,'En una sartén pequeña dora los ajos laminados con el AOVE, retira del fuego, añade el pimentón de la Vera y remueve al instante.',120),(127,42,3,'Emplata las judías y patatas con el huevo duro picado por encima y rocía con el refrito de pimentón.',60),(128,43,1,'Prepara y lava los ingredientes frescos para \"Lentejas castellanas estofadas al laurel y pimentón sin grasa\" ajustando las cantidades exactas al número de comensales activo.',180),(129,43,2,'Realiza la cocción principal mediante guiso tradicional utilizando únicamente el Aceite de Oliva Virgen Extra (AOVE) medido y caldo de verduras si requiere humedad.',675),(130,43,3,'Aplica el truco hipocalórico del chef (Emulsiona el caldo triturando una zanahoria cocida con una cucharadita de AOVE en crudo.) y emplata bien caliente o en su punto óptimo de temperatura.',525),(131,44,1,'Prepara y lava los ingredientes frescos para \"Garbanzos pedrosillanos guisados con calabaza y romero fresco\" ajustando las cantidades exactas al número de comensales activo.',180),(132,44,2,'Realiza la cocción principal mediante estofado suave utilizando únicamente el Aceite de Oliva Virgen Extra (AOVE) medido 