--
-- Table structure for table `recipes`
--

DROP TABLE IF EXISTS `recipes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `recipes` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `slug` varchar(120) NOT NULL,
  `name` varchar(180) NOT NULL,
  `category` enum('arroz_fijo','legumbre','pescado','ave_carne_magra','verdura_huevo') NOT NULL,
  `meal_slot` enum('lunch','dinner','both') NOT NULL DEFAULT 'both',
  `seasons` set('primavera','verano','otono','invierno') NOT NULL,
  `kcal` int(10) unsigned NOT NULL COMMENT 'Kcal por comensal',
  `protein_g` int(10) unsigned NOT NULL COMMENT 'Proteínas (g) por comensal',
  `carbs_g` int(10) unsigned NOT NULL COMMENT 'Hidratos (g) por comensal',
  `fat_g` int(10) unsigned NOT NULL COMMENT 'Grasas (g) por comensal',
  `prep_minutes` int(10) unsigned NOT NULL COMMENT 'Tiempo activo en minutos (<35 min)',
  `cooking_method` varchar(60) NOT NULL,
  `image_url` varchar(255) NOT NULL,
  `youtube_url` varchar(255) NOT NULL,
  `chef_tip` text NOT NULL,
  `batch_prep_tip` text NOT NULL,
  `is_friday_fixed` tinyint(1) NOT NULL DEFAULT 0,
  `source_name` varchar(120) NOT NULL DEFAULT 'Gastronomía Tradicional Española',
  `source_url` varchar(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_recipes_slug` (`slug`),
  KEY `idx_recipes_category` (`category`),
  KEY `idx_recipes_slot` (`meal_slot`)
) ENGINE=InnoDB AUTO_INCREMENT=201 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

